// Hooks returns the client hooks.
func (c *BenefitCaseClient) Hooks() []Hook {
	return c.hooks.BenefitCase
}

// Interceptors returns the client interceptors.
func (c *BenefitCaseClient) Interceptors() []Interceptor {
	return c.inters.BenefitCase
}

func (c *BenefitCaseClient) mutate(ctx context.Context, m *BenefitCaseMutation) (Value, error) {
	switch m.Op() {
	case OpCreate:
		return (&BenefitCaseCreate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdate:
		return (&BenefitCaseUpdate{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpUpdateOne:
		return (&BenefitCaseUpdateOne{config: c.config, hooks: c.Hooks(), mutation: m}).Save(ctx)
	case OpDelete, OpDeleteOne:
		return (&BenefitCaseDelete{config: c.config, hooks: c.Hooks(), mutation: m}).Exec(ctx)
	default:
		return nil, fmt.Errorf("government: unknown BenefitCase mutation op: %q", m.Op())
	}
}

// hooks and interceptors per client, for fast access.
type (
	hooks struct {
		Agency, Applicant, BenefitCase []ent.Hook
	}
	inters struct {
		Agency, Applicant, BenefitCase []ent.Interceptor
	}
)
